Prob096_review2015_fsmseq.code:
module TopModule (
    input  clk,
    input  reset,
    input  data,
    output start_shifting
);

    // State encoding: 4 states to cover the sequence 1101 detection
    // State 0: Idle (no partial match)
    // State 1: First '1' matched
    // State 2: '11' matched
    // State 3: '110' matched
    typedef enum logic [1:0] {
        S0_IDLE   = 2'b00,
        S1_1      = 2'b01,
        S2_11     = 2'b10,
        S3_110    = 2'b11
    } state_t;

    state_t state, next_state;

    // State register (synchronous reset, active high)
    always_ff @(posedge clk) begin
        if (reset)
            state <= S0_IDLE;
        else
            state <= next_state;
    end

    // Next-state logic
    always_comb begin
        case (state)
            S0_IDLE: begin
                if (data == 1'b1)
                    next_state = S1_1;
                else
                    next_state = S0_IDLE;
            end
            S1_1: begin
                if (data == 1'b1)
                    next_state = S2_11;
                else
                    next_state = S0_IDLE; // '1' followed by '0' resets to idle
            end
            S2_11: begin
                if (data == 1'b0)
                    next_state = S3_110;
                else
                    next_state = S2_11; // '11' followed by '1' keeps the second '1'
            end
            S3_110: begin
                if (data == 1'b1)
                    next_state = S0_IDLE; // Complete sequence 1101 detected
                else
                    next_state = S0_IDLE;
            end
            default: next_state = S0_IDLE;
        endcase
    end

    // Output logic: start_shifting is asserted when we transition
    // from S3_110 to S0_IDLE with data == 1 (i.e., sequence 1101 found)
    // Since start_shifting must be 1 forever after detection until reset,
    // we use a registered output that captures the detection event.
    logic start_shifting_reg;

    always_ff @(posedge clk) begin
        if (reset)
            start_shifting_reg <= 1'b0;
        else if (state == S3_110 && data == 1'b1)
            start_shifting_reg <= 1'b1;
    end

    assign start_shifting = start_shifting_reg;

endmodule

