module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic in,
    output logic out
);

    // State encoding: 2 bits for 4 states (A, B, C, D)
    typedef enum logic [1:0] {
        A = 2'b00,
        B = 2'b01,
        C = 2'b10,
        D = 2'b11
    } state_t;

    state_t state, next_state;

    // Next-state logic (combinational)
    always_comb begin
        case (state)
            A: next_state = in ? B : A;
            B: next_state = in ? B : C;
            C: next_state = in ? D : A;
            D: next_state = in ? B : C;
            default: next_state = A;
        endcase
    end

    // Output logic (Moore machine: output depends only on state)
    always_comb begin
        case (state)
            D: out = 1'b1;
            default: out = 1'b0;
        endcase
    end

    // Next-state flip-flops with synchronous active-high reset
    always_ff @(posedge clk or posedge reset) begin
        if (reset)
            state <= A;
        else
            state <= next_state;
    end

endmodule

Prob139_2013_q2bfsm.code:
module TopModule (
    input  clk,
    input  resetn,
    input  x,
    input  y,
    output f,
    output g
);

    // State encoding: 3 bits
    // State A: 3'b000
    // State B: 3'b001 (f=1, waiting for x=1,0,1 sequence)
    // State C: 3'b010 (x=1 detected, waiting for x=0)
    // State D: 3'b011 (x=0 detected, waiting for x=1)
    // State E: 3'b100 (x=1,0,1 detected, g=1, waiting for y)
    // State F: 3'b101 (y=1 detected within 2 cycles, g stays 1 permanently)
    // State G: 3'b110 (timeout, g=0 permanently)
    // State H: 3'b111 (second cycle of y-monitor)
    typedef enum logic [2:0] {
        S_A   = 3'b000,
        S_B   = 3'b001,
        S_C   = 3'b010,
        S_D   = 3'b011,
        S_E   = 3'b100,
        S_F   = 3'b101,
        S_G   = 3'b110,
        S_H   = 3'b111
    } state_t;

    state_t state, next_state;

    // Output assignments
    // f is 1 only in state B
    assign f = (state == S_B) ? 1'b1 : 1'b0;

    // g is 1 in states E and F, 0 in state G, 0 elsewhere
    assign g = (state == S_E || state == S_F) ? 1'b1 : 1'b0;

    // State register
    always_ff @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= S_A;
        end else begin
            state <= next_state;
        end
    end

    // Next-state logic
    always_comb begin
        case (state)
            S_A: begin
                // On de-assertion of reset, go to S_B and set f=1 for one cycle
                next_state = S_B;
            end

            S_B: begin
                // Waiting for x=1
                if (x == 1'b1)
                    next_state = S_C;
                else
                    next_state = S_B; // stay in S_B
            end

            S_C: begin
                // We have seen x=1, now waiting for x=0
                if (x == 1'b0)
                    next_state = S_D;
                else
                    next_state = S_C; // stay in S_C if x remains 1
            end

            S_D: begin
                // We have seen x=1,0, now waiting for x=1 to complete the sequence
                if (x == 1'b1)
                    next_state = S_E;
                else
                    next_state = S_B; // reset to S_B if x is 0 again
            end

            S_E: begin
                // x=1,0,1 sequence detected. g goes 1 on the next cycle.
                // Start monitoring y with a 2-cycle timeout.
                // From S_E, go to S_F (first cycle of y-monitor).
                next_state = S_F;
            end

            S_F: begin
                // First cycle of y-monitor.
                if (y == 1'b1)
                    next_state = S_F; // y=1 seen, stay in S_F, g stays 1
                else
                    next_state = S_H; // y=0, go to second cycle check
            end

            S_H: begin
                // Second cycle of y-monitor.
                if (y == 1'b1)
                    next_state = S_F; // y=1 seen, go to permanent state
                else
                    next_state = S_G; // timeout, g=0 permanently
            end

            S_G: begin
                // Timeout: g=0 permanently. Stay in S_G regardless of inputs.
                next_state = S_G;
            end

            default: next_state = S_A;
        endcase
    end

endmodule

