    output ena    // 3 bits: enable for tens, hundreds, thousands
    output q      // 16 bits: BCD count value
);

    // Internal registers for the 4 BCD digits
    // q[3:0]  -> ones
    // q[7:4]  -> tens
    // q[11:8] -> hundreds
    // q[15:12] -> thousands
    reg  [3:0] ones;
    reg  [3:0] tens;
    reg  [3:0] hundreds;
    reg  [3:0] thousands;

    // enable signals for the upper three digits
    // ena[0] -> tens enable (when ones rolls over from 9 to 0)
    // ena[1] -> hundreds enable (when tens rolls over from 9 to 0)
    // ena[2] -> thousands enable (when hundreds rolls over from 9 to 0)
    wire ena_tens;
    wire ena_hundreds;
    wire ena_thousands;

    // Assign the 3-bit ena output
    assign ena = {ena_thousands, ena_hundreds, ena_tens};

    // BCD adder / increment logic for ones digit
    // ones increments every clock cycle; when it reaches 10 (b'1010),
    // it wraps to 0 and asserts the tens enable.
    always @(posedge clk) begin
        if (reset) begin
            ones   <= 4'b0;
            tens   <= 4'b0;
            hundreds <= 4'b0;
            thousands <= 4'b0;
        end else begin
            // ones increment with wrap-around at 10
            if (ones == 4'd9) begin
                ones <= 4'b0;
            end else begin
                ones <= ones + 1'b1;
            end

            // tens increment only when ones wrapped
            if (ones == 4'd9) begin
                if (tens == 4'd9) begin
                    tens <= 4'b0;
                end else begin
                    tens <= tens + 1'b1;
                end
            end else begin
                tens <= tens; // hold
            end

            // hundreds increment only when tens wrapped
            if (tens == 4'd9 && ones == 4'd9) begin
                if (hundreds == 4'd9) begin
                    hundreds <= 4'b0;
                end else begin
                    hundreds <= hundreds + 1'b1;
                end
            end else begin
                hundreds <= hundreds; // hold
            end

            // thousands increment only when hundreds wrapped
            if (hundreds == 4'd9 && tens == 4'd9 && ones == 4'd9) begin
                if (thousands == 4'd9) begin
                    thousands <= 4'b0;
                end else begin
                    thousands <= thousands + 1'b1;
                end
            end else begin
                thousands <= thousands; // hold
            end
        end
    end

    // Assign enable signals based on wrap conditions
    // ena_tens: high when ones rolled over (ones == 9 at end of cycle)
    assign ena_tens = (ones == 4'd9) ? 1'b1 : 1'b0;

    // ena_hundreds: high when tens and ones both rolled over
    assign ena_hundreds = (tens == 4'd9 && ones == 4'd9) ? 1'b1 : 1'b0;

    // ena_thousands: high when hundreds, tens and ones all rolled over
    assign ena_thousands = (hundreds == 4'd9 && tens == 4'd9 && ones == 4'd9) ? 1'b1 : 1'b0;

    // Concatenate the four digits into the 16-bit output q
    assign q = {thousands, hundreds, tens, ones};

endmodule

