module TopModule (
    input  d,
    input  done_counting,
    input  ack,
    input  state [9:0],
    output B3_next,
    output S_next,
    output S1_next,
    output Count_next,
    output Wait_next,
    output done,
    output counting,
    output shift_ena
);

    // One-hot decode: Encoding (S, S1, S11, S110, B0, B1, B2, B3, Count, Wait) = (bit 0, bit 1, bit 2, bit 3, bit 4, bit 5, bit 6, bit 7, bit 8, bit 9)
    wire cur_S   = state[0];
    wire cur_S1  = state[1];
    wire cur_S11 = state[2];
    wire cur_S110= state[3];
    wire cur_B0  = state[4];
    wire cur_B1  = state[5];
    wire cur_B2  = state[6];
    wire cur_B3  = state[7];
    wire cur_Count = state[8];
    wire cur_Wait  = state[9];

    // ============================================================
    // Next-state logic (one-hot asserted for the next state)
    // ============================================================

    // S_next: next state is S
    // From diagram: S --d=0--> S, S1 --d=0--> S, S110 --d=0--> S, Wait --ack=1--> S
    assign S_next = (cur_S   & ~d) |
                    (cur_S1  & ~d) |
                    (cur_S110& ~d) |
                    (cur_Wait& ack);

    // S1_next: next state is S1
    // From diagram: S --d=1--> S1 (only transition to S1)
    assign S1_next = cur_S & d;

    // S11_next: next state is S11
    // From diagram: S1 --d=1--> S11, S11 --d=1--> S11
    assign S11_next = (cur_S1 | cur_S11) & d;

    // S110_next: next state is S110
    // From diagram: S11 --d=0--> S110
    assign S110_next = cur_S11 & ~d;

    // B3_next: next state is B3
    // From diagram: B2 --always--> B3
    assign B3_next = cur_B2;

    // Count_next: next state is Count
    // From diagram: B3 --> Count, Count --done_counting=0--> Count
    assign Count_next = cur_B3 | (cur_Count & ~done_counting);

    // Wait_next: next state is Wait
    // From diagram: Count --done_counting=1--> Wait
    assign Wait_next = cur_Count & done_counting;

    // ============================================================
    // Output logic (Moore outputs)
    // ============================================================

    // shift_ena: 1 in states B0, B1, B2, B3
    assign shift_ena = cur_B0 | cur_B1 | cur_B2 | cur_B3;

    // counting: 1 in Count state
    assign counting = cur_Count;

    // done: 1 in Wait state
    assign done = cur_Wait;

endmodule
